WITH Src AS (SELECT *, ADD_MONTHS(last_restock, 12) AS last_restock_plus_months FROM inventory WHERE quantity >= 192 OR last_restock BETWEEN '2023-03-01' AND '2023-03-25'), product_id_summary AS (SELECT product_id, MAX(last_restock_plus_months) AS latest_last_restock_plus_months FROM Src GROUP BY product_id) SELECT * FROM product_id_summary ORDER BY product_id DESC, latest_last_restock_plus_months LIMIT 3;
